from __future__ import annotations


def styles() -> str:
    return """
:root { color-scheme: light; --app:#f8f9fb; --surface:#fff; --ink:#263238; --muted:#65727b; --faint:#8b969e; --line:#e4e8eb; --hover:#f1f4f6; --dark:#263238; --danger:#a83f3f; --success:#287a4a; --warning:#966d17; --blue:#1555bd; --radius:10px; font-family:Inter,"Segoe UI",Roboto,Arial,sans-serif; }
* { box-sizing:border-box; } body { margin:0; color:var(--ink); background:var(--app); font-size:13px; line-height:1.45; } button,input,select,textarea { font:inherit; } a { color:inherit; text-decoration:none; } h1,h2,h3,p { margin:0; } h1 { font-size:24px; line-height:1.2; letter-spacing:-.025em; font-weight:650; } h2 { font-size:15px; letter-spacing:-.01em; font-weight:650; } h3 { font-size:13px; font-weight:650; } .eyebrow { color:var(--faint); font-size:10px; font-weight:650; letter-spacing:.08em; text-transform:uppercase; } .lede { color:var(--muted); font-size:13px; line-height:1.55; margin-top:7px; max-width:640px; } .mono,code { font-family:"SFMono-Regular",Consolas,monospace; } .mono { font-size:.62em; font-weight:500; letter-spacing:0; }
.app-shell { display:grid; grid-template-columns:220px minmax(0,1fr); min-height:100vh; } .navigation-drawer { background:#fff; border-right:1px solid var(--line); display:flex; flex-direction:column; gap:28px; padding:12px 12px 16px; } .brand { align-items:center; display:flex; gap:9px; min-height:32px; padding:2px 4px; } .brand strong { display:block; font-size:12px; letter-spacing:.065em; } .brand small { color:var(--muted); display:block; font-size:10px; margin-top:-1px; } .brand-mark { align-items:center; background:#263238; border-radius:7px; color:#fff; display:inline-flex; height:28px; justify-content:center; width:28px; } .brand-mark svg { fill:none; height:17px; stroke:currentColor; stroke-linecap:round; stroke-linejoin:round; stroke-width:1.7; width:17px; } .nav-list { display:grid; gap:2px; } .nav-item { align-items:center; border-radius:6px; color:#68747c; display:flex; font-size:12px; font-weight:550; gap:10px; min-height:31px; padding:0 9px; } .nav-item span { color:#909ba2; font-size:16px; line-height:1; text-align:center; width:14px; } .nav-item:hover,.nav-item--active { background:#eef1f3; color:var(--ink); } .drawer-footer { align-items:center; color:var(--muted); display:flex; font-size:10px; gap:7px; margin-top:auto; padding:0 8px; } .environment-dot { background:var(--success); border-radius:100%; height:6px; width:6px; }
.app-main { min-width:0; } .topbar { align-items:center; background:rgba(255,255,255,.94); border-bottom:1px solid var(--line); display:flex; height:48px; justify-content:space-between; padding:0 24px; position:sticky; top:0; z-index:2; } .breadcrumb { align-items:center; color:var(--muted); display:flex; font-size:11px; gap:7px; } .breadcrumb strong { color:var(--ink); font-weight:550; } .account { align-items:center; display:flex; gap:8px; } .account form { margin:0; } .avatar { align-items:center; background:#e8e1f5; border-radius:50%; color:#493266; display:inline-flex; font-size:10px; font-weight:650; height:24px; justify-content:center; width:24px; } .account-email { color:#666; font-size:11px; } .icon-button { background:transparent; border:0; border-radius:5px; color:#777; cursor:pointer; font-size:15px; height:28px; width:28px; } .icon-button:hover { background:var(--hover); color:var(--ink); } .page-content { margin:0 auto; max-width:1440px; padding:34px 40px 56px; }
.page-heading { align-items:flex-end; display:flex; gap:20px; justify-content:space-between; margin-bottom:24px; } .page-heading--compact { align-items:center; } .heading-actions { align-items:center; display:flex; flex-wrap:wrap; gap:8px; } .metric-grid { display:grid; gap:12px; grid-template-columns:repeat(4,minmax(0,1fr)); margin-bottom:18px; } .metric-grid--summary { grid-template-columns:repeat(auto-fit,minmax(145px,1fr)); } .metric-card { background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); display:flex; flex-direction:column; min-height:102px; padding:14px; } .metric-card span { color:var(--muted); font-size:11px; } .metric-card strong { font-size:24px; font-weight:550; letter-spacing:-.035em; line-height:1.15; margin:6px 0 auto; } .metric-card small { color:var(--faint); font-size:10px; line-height:1.3; }
.work-grid { display:grid; gap:18px; grid-template-columns:minmax(0,1.35fr) minmax(280px,.85fr); margin-bottom:18px; } .panel,.job-state { background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); } .panel { padding:18px; } .panel-header { align-items:flex-start; display:flex; justify-content:space-between; margin-bottom:6px; } .panel-header h2 { margin-top:2px; } .panel-icon { align-items:center; background:#f1f3f4; border-radius:6px; color:#667078; display:inline-flex; font-size:16px; height:28px; justify-content:center; width:28px; } .panel-copy { color:var(--muted); font-size:11px; line-height:1.55; margin:10px 0 15px; max-width:62ch; } .panel-meta { color:var(--muted); font-size:11px; padding-top:3px; }
form { margin:0; } label { color:#56616a; display:grid; font-size:11px; font-weight:550; gap:5px; } input,select,textarea { background:#fff; border:1px solid #cfd7dc; border-radius:5px; color:var(--ink); min-height:32px; outline:none; padding:6px 8px; transition:border-color .15s,box-shadow .15s; width:100%; } input[type=file] { background:#fafafa; font-size:11px; padding:5px; } textarea { min-height:84px; resize:vertical; } input:focus,select:focus,textarea:focus { border-color:#65727b; box-shadow:0 0 0 3px rgba(30,30,30,.08); } .form-grid { display:grid; gap:12px; grid-template-columns:repeat(2,minmax(0,1fr)); } .stack-form { display:grid; gap:11px; } .field-span-2 { grid-column:span 2; } .field-hint { color:var(--faint); font-size:10px; font-weight:400; } .form-actions { align-items:center; display:flex; gap:8px; margin-top:2px; }
.button { align-items:center; border:1px solid transparent; border-radius:5px; cursor:pointer; display:inline-flex; font-size:11px; font-weight:550; gap:7px; justify-content:center; min-height:32px; padding:0 11px; white-space:nowrap; } .button--primary { background:var(--dark); color:#fff; } .button--primary:hover { background:#111b20; } .button--secondary { background:#fff; border-color:#cfd7dc; color:#44515a; } .button--secondary:hover { background:#f5f7f8; } .button--danger { background:#fff; border-color:#e4bebe; color:var(--danger); } .button--danger:hover { background:#fff4f4; }
.table-panel { padding:0; overflow:hidden; } .table-panel .panel-header { padding:18px 18px 10px; } .table-wrap { overflow:auto; } table { border-collapse:collapse; min-width:600px; width:100%; } th { background:#fbfcfc; border-bottom:1px solid var(--line); color:#7f8a91; font-size:10px; font-weight:650; letter-spacing:.045em; padding:9px 18px; text-align:left; text-transform:uppercase; } td { border-bottom:1px solid var(--line); color:#55616a; font-size:11px; padding:11px 18px; vertical-align:middle; } tr:last-child td { border-bottom:0; } tbody tr:hover td { background:#fdfdfd; } .job-link { color:#263238; font-family:"SFMono-Regular",Consolas,monospace; font-size:10px; } .job-link:hover { color:var(--blue); text-decoration:underline; } .empty-cell { color:var(--faint); padding:28px 18px; text-align:center; } .status-badge { border-radius:999px; display:inline-flex; font-size:10px; font-weight:650; line-height:1; padding:5px 8px; } .status-badge--running { background:#e8f0ff; color:#2557ab; } .status-badge--queued { background:#f2f2f2; color:#666; } .status-badge--cancelling,.status-badge--cancelled { background:#fceaea; color:#a33d3d; } .status-badge--succeeded { background:#e6f5eb; color:#287247; } .status-badge--failed,.status-badge--exhausted { background:#f9eeee; color:#a44444; } .status-badge--not-found,.status-badge--excluded { background:#fff5de; color:#906815; }
.settings-panel { background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); margin-top:18px; overflow:hidden; } .settings-panel summary { align-items:center; cursor:pointer; display:flex; justify-content:space-between; list-style:none; padding:16px 18px; } .settings-panel summary::-webkit-details-marker { display:none; } .settings-panel summary strong { display:block; font-size:13px; margin-top:2px; } .summary-action { color:var(--muted); font-size:11px; } .admin-grid { border-top:1px solid var(--line); display:grid; gap:1px; grid-template-columns:repeat(2,minmax(0,1fr)); background:var(--line); } .mini-panel { background:#fff; padding:18px; } .mini-panel--wide { grid-column:span 2; } .mini-panel h3 { margin-bottom:3px; } .mini-panel p { color:var(--muted); font-size:11px; line-height:1.5; margin-bottom:13px; }
.search-bar { align-items:end; display:grid; gap:10px; grid-template-columns:minmax(160px,1fr) minmax(160px,1fr) auto; } .job-state { align-items:center; display:flex; justify-content:space-between; margin-bottom:18px; padding:18px; } .state-line { align-items:center; color:var(--muted); display:flex; font-size:11px; gap:9px; margin-top:6px; } .progress-copy { color:var(--muted); display:flex; font-size:11px; justify-content:space-between; margin:18px 0 6px; } .progress-copy strong { color:var(--ink); } .progress-track { background:#e8ecef; border-radius:999px; height:7px; overflow:hidden; } .progress-track span { background:var(--blue); border-radius:999px; display:block; height:100%; transition:width .2s; } .pagination { display:flex; justify-content:flex-end; margin-top:14px; } .flash { border-radius:6px; font-size:11px; margin-top:14px; padding:9px 11px; } .flash--error { background:#fff0f0; color:#9b3434; } .auth-page { align-items:center; background:#f7f8f9; display:flex; justify-content:center; min-height:100vh; padding:24px; } .auth-shell { max-width:390px; width:100%; } .brand--auth { justify-content:center; margin-bottom:22px; } .auth-card { background:#fff; border:1px solid var(--line); border-radius:12px; padding:28px; } .auth-card h1 { margin-top:4px; } .auth-card .stack-form { margin-top:22px; } .auth-card .button { margin-top:4px; width:100%; } .helper-text,.auth-footer { color:var(--faint); font-size:10px; line-height:1.5; } .helper-text { margin-top:16px; } .auth-footer { margin-top:18px; text-align:center; }
@media (max-width:820px) { .app-shell { grid-template-columns:1fr; } .navigation-drawer { display:none; } .page-content { padding:24px 18px 40px; } .topbar { padding:0 18px; } .metric-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .work-grid { grid-template-columns:1fr; } } @media (max-width:520px) { .account-email { display:none; } .page-heading { align-items:flex-start; flex-direction:column; } .metric-grid { gap:8px; } .metric-card { min-height:92px; padding:12px; } .form-grid,.admin-grid { grid-template-columns:1fr; } .field-span-2,.mini-panel--wide { grid-column:auto; } .search-bar { grid-template-columns:1fr; } .search-bar .button { width:100%; } .heading-actions { width:100%; } .heading-actions > * { flex:1; } .state-line { align-items:flex-start; flex-direction:column; gap:5px; } }
"""
